// 에디터가 파일 바뀜을 보내면 → 파싱해서 오류를 돌려준다
connection.onDidChangeTextDocument((params) => {
  const text = documents.get(params.textDocument.uri);
  const diagnostics = parseAndCheck(text);       // 파서로 오류 찾기(3장)
  connection.sendDiagnostics({                   // 서버 → 에디터
    uri: params.textDocument.uri,
    diagnostics                                  // [{ range:{start,end}, message, severity }]
  });
});
// 자동완성 요청에 응답
connection.onCompletion((params) => {
  return getCompletions(params.position);        // 커서 위치의 후보들
});

